insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (88, 6, 1, 19, 'سورة الأنعام ١ – ١٩', 'افتتاح سورة الأنعام: الحمد لله الخالق، و«كتب على نفسه الرحمة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 88) = $j$[{"lbl": "الآيات ١ – ٣", "q": "ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَۖ ثُمَّ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡ يَعۡدِلُونَ ﴿١﴾ هُوَ ٱلَّذِي خَلَقَكُم مِّن طِينٖ ثُمَّ قَضَىٰٓ أَجَلٗاۖ وَأَجَلٞ مُّسَمًّى عِندَهُۥۖ ثُمَّ أَنتُمۡ تَمۡتَرُونَ ﴿٢﴾ وَهُوَ ٱللَّهُ فِي ٱلسَّمَٰوَٰتِ وَفِي ٱلۡأَرۡضِ يَعۡلَمُ سِرَّكُمۡ وَجَهۡرَكُمۡ وَيَعۡلَمُ مَا تَكۡسِبُونَ ﴿٣﴾", "w": [["الحمد", "الثناء باللسان على المحمود بصفات الجلال والكمال."], ["خلق", "أنشأ وأوجد."], ["يعدلون", "يسوّون به غيره فيعبدونه معه."], ["أجلاً", "الأجل: الوقت المحدد لعمل ما يتم فيه أو ينتهي، والأجل الأول أجل كل إنسان، والثاني أجل الدنيا."], ["تمترون", "تشكّون في البعث والجزاء، وفي وجوب توحيده بعبادته وحده."], ["ما تكسبون", "من خير وشر، وصلاح وفساد."]], "m": "يخبر الله أنه المستحق للحمد كله، وضمن ذلك يأمر عباده أن يحمدوه، ثم ذكر موجبات حمده: الذي خلق السموات والأرض وجعل الظلمات والنور، وهما من أقوى عناصر الحياة، فهو المستحق للحمد لا غيره، ومع هذا فالذين كفروا بربهم يعدلون به غيره. ثم خاطب المشركين موبّخاً: هو الذي خلقكم من طين، إذ خلق أباكم آدم منه، ثم قضى لكل أحد أجلاً هو عمره، وأجلُ الحياة كلها مسمّى عنده لا يعلمه غيره، ثم أنتم أيها المشركون تشكّون في وجوب توحيده وقدرته على بعثكم. وهو الله المعبود بحق في السموات وفي الأرض، فوق عرشه بائن من خلقه، يعلم سرّكم وجهركم ويعلم ما تكسبون، لذا وجبت الرغبة فيما عنده والرهبة مما لديه، بالإنابة إليه وعبادته والتوكل عليه.", "h": ["وجوب حمد الله تعالى والثناء عليه بما هو أهله.", "لا يصح حمد أحد بدون ما يوجد لديه من صفات الكمال ما يُحمد عليه.", "التعجب من حال من يسوّون المخلوقات بالخالق عز وجل في العبادة.", "التعجب من حال من يرى عجائب صنع الله ومظاهر قدرته ثم ينكر البعث والحياة الآخرة.", "صفة العلم لله تعالى، وأنه لا يخفى عليه شيء في الأرض ولا في السماء، يعلم السر وأخفى."], "k": "«الحمد لله الذي خلق السموات والأرض»… على أي نعمة من خلقه أحمده اليوم بقلب حاضر؟"}, {"lbl": "الآيات ٤ – ٦", "q": "وَمَا تَأۡتِيهِم مِّنۡ ءَايَةٖ مِّنۡ ءَايَٰتِ رَبِّهِمۡ إِلَّا كَانُواْ عَنۡهَا مُعۡرِضِينَ ﴿٤﴾ فَقَدۡ كَذَّبُواْ بِٱلۡحَقِّ لَمَّا جَآءَهُمۡ فَسَوۡفَ يَأۡتِيهِمۡ أَنۢبَـٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٥﴾ أَلَمۡ يَرَوۡاْ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنٖ مَّكَّنَّـٰهُمۡ فِي ٱلۡأَرۡضِ مَا لَمۡ نُمَكِّن لَّكُمۡ وَأَرۡسَلۡنَا ٱلسَّمَآءَ عَلَيۡهِم مِّدۡرَارٗا وَجَعَلۡنَا ٱلۡأَنۡهَٰرَ تَجۡرِي مِن تَحۡتِهِمۡ فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ ﴿٦﴾", "w": [["آية", "آيات القرآن الدالة على توحيد الله تعالى."], ["معرضين", "غير ملتفتين إليها ولا مفكّرين فيها."], ["الحق", "النبي ﷺ وما جاء به من الدين الحق."], ["أنباء", "أخبار ما كانوا به يستهزئون، وهو عذاب الدنيا وعذاب الآخرة."], ["من قرن", "أهل قرن من الأمم السابقة، والقرن: مائة سنة."], ["مكّنّاهم في الأرض", "أعطيناهم من القوة المادية ما لم نعطِ هؤلاء المشركين."], ["مدراراً", "مطراً متواصلاً غزيراً."], ["بذنوبهم", "بسبب ذنوبهم، وهي معصية الله ورسله."], ["وأنشأنا", "خلقنا بعد إهلاك الأولين."]], "m": "ما زال السياق في الذين يعدلون بربهم: ما تأتيهم من آية من آيات ربهم إلا قابلوها بالإعراض التام، وسبب ذلك أنهم كذّبوا بالحق لما جاءهم، وهو الرسول وما معه، فسوف يأتيهم أنباء ما كانوا به يستهزئون، وأول ذلك هزيمتهم يوم بدر، ثم القحط سبع سنين، ومن مات على الشرك فإلى نار جهنم. ألم يروا كم أهلكنا من قبلهم من قرن، مكّنّاهم في الأرض من الدولة والسلطان والمال ما لم نمكّن لكفار قريش، وأرسلنا السماء عليهم مدراراً، وجعلنا الأنهار تجري من تحت أشجارهم وقصورهم، فلما أنكروا التوحيد وكذّبوا الرسل أهلكناهم بذنوبهم، لا ظلماً منا، وأنشأنا من بعدهم قرناً آخرين، وكان ذلك علينا يسيراً.", "h": ["التكذيب بالحق هو سبب الإعراض عنه، فلو آمنوا به لأقبلوا عليه.", "الاستهزاء والسخرية بالدين من موجبات العذاب وقرب وقوعه.", "العبرة بهلاك الماضين ومصارع الظالمين.", "هلاك الأمم كان بسبب ذنوبهم، فما من مصيبة إلا بذنب."], "k": "«فأهلكناهم بذنوبهم»… هل أعدّ ذنوبي سبباً لما يصيبني من ضيق، فأتوب منها؟"}, {"lbl": "الآيات ٧ – ١١", "q": "وَلَوۡ نَزَّلۡنَا عَلَيۡكَ كِتَٰبٗا فِي قِرۡطَاسٖ فَلَمَسُوهُ بِأَيۡدِيهِمۡ لَقَالَ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ ﴿٧﴾ وَقَالُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ مَلَكٞۖ وَلَوۡ أَنزَلۡنَا مَلَكٗا لَّقُضِيَ ٱلۡأَمۡرُ ثُمَّ لَا يُنظَرُونَ ﴿٨﴾ وَلَوۡ جَعَلۡنَٰهُ مَلَكٗا لَّجَعَلۡنَٰهُ رَجُلٗا وَلَلَبَسۡنَا عَلَيۡهِم مَّا يَلۡبِسُونَ ﴿٩﴾ وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُواْ مِنۡهُم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿١٠﴾ قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ ثُمَّ ٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ ﴿١١﴾", "w": [["قرطاساً", "ما يُكتب عليه، جلداً كان أو ورقاً."], ["لمسوه بأيديهم", "مسّوه بأصابعهم ليتأكدوا منه."], ["ملَك", "أحد الملائكة."], ["لقُضي الأمر", "أُهلكوا وانتهت حياتهم."], ["ثم لا يُنظرون", "لا يُمهلون."], ["ولو جعلناه ملكاً", "ولو جعلنا الرسول إليهم ملكاً لإنكارهم البشر."], ["للبسنا", "لخلطنا عليهم."], ["استُهزئ", "سُخر به وتُهكّم."], ["حاق بهم", "نزل بهم العذاب وأحاط بهم فأُهلكوا."]], "m": "ما زال السياق في العادلين بربهم أصنامهم: ولو نزّلنا عليك كتاباً مكتوباً في ورق فرأوه منزلاً من السماء ولمسوه بأيديهم، ما آمنوا، ولقالوا: إن هذا إلا سحر مبين. وقالوا: لولا أُنزل عليه ملك يصدّقه، ولو أنزلنا ملكاً فكذّبوه لقُضي الأمر بإهلاكهم ثم لا يُمهلون ساعة ليتوبوا، إذ الملائكة لا تنزل إلا لإحقاق الحق. ولو جعلنا الرسول ملكاً لقالوا: كيف نفهم عن الملك ونحن بشر؟ فلجعلناه رجلاً، وللبسنا عليهم ما يلبسون. ثم سلّى رسوله: ولقد استُهزئ برسل من قبلك فاصبر، فحاق بالذين سخروا منهم ما كانوا به يستهزئون. ثم أمره أن يقول لأكابر مجرمي قريش: سيروا في الأرض، جنوباً إلى ديار عاد، أو شمالاً إلى ديار ثمود، أو غرباً إلى بحيرة لوط، ثم انظروا كيف كان عاقبة المكذبين، لعلكم تكفّون عن طغيانكم.", "h": ["الآيات بمعنى المعجزات والخوارق لا تستلزم الإيمان، بل قد تكون سبباً للكفر والعناد، ولذا لم يعطِ الله رسوله ما طالبت به قريش.", "إنكار رسالة البشر عام في كل الأمم، في حين أن إرسال الملائكة لا يتم معه هدف لعدم قدرة الإنسان على التلقّي عنهم.", "الاستهزاء بالرسل والدعاة سنة بشرية لا تكاد تتخلّف، ولذا وجب على الرسل والدعاة الصبر على ذلك.", "عاقبة التكذيب والاستهزاء هلاك المكذبين المستهزئين.", "مشروعية زيارة القبور للوقوف على مصير الإنسان ومآل أمره، فإن في ذلك ما يخفّف شهوة الدنيا والتكالب عليها، وهو سبب الظلم والفساد."], "k": "متى آخر مرة زرت المقابر، أو تأملت في آثار الماضين، فخفّت الدنيا في قلبي؟"}, {"lbl": "الآيات ١٢ – ١٦", "q": "قُل لِّمَن مَّا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُل لِّلَّهِۚ كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِۚ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فَهُمۡ لَا يُؤۡمِنُونَ ﴿١٢﴾ ۞وَلَهُۥ مَا سَكَنَ فِي ٱلَّيۡلِ وَٱلنَّهَارِۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿١٣﴾ قُلۡ أَغَيۡرَ ٱللَّهِ أَتَّخِذُ وَلِيّٗا فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَهُوَ يُطۡعِمُ وَلَا يُطۡعَمُۗ قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَكُونَ أَوَّلَ مَنۡ أَسۡلَمَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ ﴿١٤﴾ قُلۡ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ ﴿١٥﴾ مَّن يُصۡرَفۡ عَنۡهُ يَوۡمَئِذٖ فَقَدۡ رَحِمَهُۥۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡمُبِينُ ﴿١٦﴾", "w": [["لا ريب فيه", "لا شك في مجيئه وحصوله في أجله المحدد له."], ["خسروا أنفسهم", "لوّثوها بأوضار الشرك والمعاصي فلم ينتفعوا بها."], ["وله ما سكن في الليل والنهار", "ما استقر فيهما من ساكن ومتحرك، أي له كل شيء."], ["ولياً", "أحبه وأنصره، وأطلب نصرته ومحبته وولايته."], ["الفوز المبين", "الواضح، إذ النجاة من النار ودخول الجنة هو الفوز."]], "m": "ما زال السياق مع العادلين بربهم: قل لمن ما في السموات والأرض؟ واسبقهم إلى الجواب: قل لله، الذي كتب على نفسه الرحمة، ومظاهرها متجلّية: إنهم يكفرونه ويعصونه وهو يطعمهم ويسقيهم ويحفظهم، ومن رحمته جمعه الناس ليوم القيامة ليجزيهم، الحسنة بعشر أمثالها والسيئة بمثلها، ليجمعنّكم إلى يوم القيامة لا ريب فيه، الذين خسروا أنفسهم فهم لا يؤمنون. وله ما سكن في الليل والنهار، وهو السميع العليم، فوجب اللجوء إليه والتوكل عليه. ثم أمر رسوله أن يردّ على المشركين الذين طالبوه بموافقتهم على شركهم: أغير الله أتخذ ولياً، فاطر السموات والأرض، وهو يُطعم غيره لافتقارهم إليه ولا يُطعم لغناه المطلق؟ قل إني أُمرت أن أكون أول من أسلم، ولا تكوننّ من المشركين. قل إني أخاف إن عصيت ربي عذاب يوم عظيم، من يُصرف عنه يومئذ فقد رحمه، وذلك الفوز المبين.", "h": ["عموم رحمة الله تعالى.", "تقرير مبدأ الشقاوة والسعادة في الأزل قبل خلق الخلق.", "الله رب كل شيء ومليكه.", "تحريم ولاية غير الله، وتحريم الشرك به تعالى.", "بيان الفوز الأخروي، وهو النجاة من العذاب ودخول الجنة."], "k": "«كتب على نفسه الرحمة»… كم مرة عصيته فلم يقطع عني رزقه؟ أفلا يستحق مني الحياء؟"}, {"lbl": "الآيات ١٧ – ١٩", "q": "وَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرّٖ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن يَمۡسَسۡكَ بِخَيۡرٖ فَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿١٧﴾ وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ ﴿١٨﴾ قُلۡ أَيُّ شَيۡءٍ أَكۡبَرُ شَهَٰدَةٗۖ قُلِ ٱللَّهُۖ شَهِيدُۢ بَيۡنِي وَبَيۡنَكُمۡۚ وَأُوحِيَ إِلَيَّ هَٰذَا ٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۚ أَئِنَّكُمۡ لَتَشۡهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخۡرَىٰۚ قُل لَّآ أَشۡهَدُۚ قُلۡ إِنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ وَإِنَّنِي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ ﴿١٩﴾", "w": [["يمسسك", "يصبك."], ["بضرّ", "الضر: ما يؤلم الجسم أو النفس كالمرض والحزن."], ["بخير", "الخير: كل ما يُسعد الجسم أو الروح."], ["القاهر", "الغالب المذلّ المعزّ."], ["شهادة", "الشهادة: إخبار العالم بالشيء عنه بما لا يخالفه."], ["لأنذركم به", "لأخوّفكم بما فيه من وعيد الله لأهل عداوته."], ["إله واحد", "معبود واحد، لأنه رب واحد، إذ لا يُعبد إلا الرب الخالق الرازق المدبّر."]], "m": "ما زال السياق في تقوية موقف الرسول ﷺ من المشركين: وإن يمسسك الله بضرّ في بدنك فلا كاشف له إلا هو، وإن يمسسك بخير فهو على كل شيء قدير، فلا رادّ لفضله، والخطاب وإن كان للرسول فهو عام في كل أحد. وهو القاهر فوق عباده، وهو الحكيم الخبير، وقهره لكل أحد وعلوّه وعلمه موجب لألوهيته وبطلان عبادة غيره. ولما قال المشركون: ائتنا بمن يشهد لك بالنبوة، فإن أهل الكتاب أنكروها، أمره أن يقول: أي شيء أكبر شهادة؟ قل الله شهيد بيني وبينكم، وشهادته لي إيحاؤه إليّ هذا القرآن لأنذركم به ومن بلغ، فكل من بلغه ولم يؤمن به فهو خاسر. ثم أمره أن ينكر عليهم: أئنكم لتشهدون أن مع الله آلهة أخرى؟ قل لا أشهد، قل إنما هو إله واحد وإنني بريء مما تشركون.", "h": ["وجوب اللجوء إلى الله تعالى دون غيره من سائر خلقه، إذ لا يكشف الضر إلا هو.", "شهادة الله تعالى لرسوله بالنبوة، وما أنزل عليه من القرآن، وما أعطاه من المعجزات.", "نذارة الرسول ﷺ بلغت كل من بلغه القرآن الكريم إلى يوم الدين.", "تقرير مبدأ التوحيد: لا إله إلا الله، ووجوب البراءة من الشرك."], "k": "«وإن يمسسك الله بضرّ فلا كاشف له إلا هو»… إلى من ألجأ أولاً حين يصيبني همّ أو مرض؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 88;
insert into public.tdb_cards(topic, i, body) select 88, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٣", "q": "ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَۖ ثُمَّ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡ يَعۡدِلُونَ ﴿١﴾ هُوَ ٱلَّذِي خَلَقَكُم مِّن طِينٖ ثُمَّ قَضَىٰٓ أَجَلٗاۖ وَأَجَلٞ مُّسَمًّى عِندَهُۥۖ ثُمَّ أَنتُمۡ تَمۡتَرُونَ ﴿٢﴾ وَهُوَ ٱللَّهُ فِي ٱلسَّمَٰوَٰتِ وَفِي ٱلۡأَرۡضِ يَعۡلَمُ سِرَّكُمۡ وَجَهۡرَكُمۡ وَيَعۡلَمُ مَا تَكۡسِبُونَ ﴿٣﴾", "w": [["الحمد", "الثناء باللسان على المحمود بصفات الجلال والكمال."], ["خلق", "أنشأ وأوجد."], ["يعدلون", "يسوّون به غيره فيعبدونه معه."], ["أجلاً", "الأجل: الوقت المحدد لعمل ما يتم فيه أو ينتهي، والأجل الأول أجل كل إنسان، والثاني أجل الدنيا."], ["تمترون", "تشكّون في البعث والجزاء، وفي وجوب توحيده بعبادته وحده."], ["ما تكسبون", "من خير وشر، وصلاح وفساد."]], "m": "يخبر الله أنه المستحق للحمد كله، وضمن ذلك يأمر عباده أن يحمدوه، ثم ذكر موجبات حمده: الذي خلق السموات والأرض وجعل الظلمات والنور، وهما من أقوى عناصر الحياة، فهو المستحق للحمد لا غيره، ومع هذا فالذين كفروا بربهم يعدلون به غيره. ثم خاطب المشركين موبّخاً: هو الذي خلقكم من طين، إذ خلق أباكم آدم منه، ثم قضى لكل أحد أجلاً هو عمره، وأجلُ الحياة كلها مسمّى عنده لا يعلمه غيره، ثم أنتم أيها المشركون تشكّون في وجوب توحيده وقدرته على بعثكم. وهو الله المعبود بحق في السموات وفي الأرض، فوق عرشه بائن من خلقه، يعلم سرّكم وجهركم ويعلم ما تكسبون، لذا وجبت الرغبة فيما عنده والرهبة مما لديه، بالإنابة إليه وعبادته والتوكل عليه.", "h": ["وجوب حمد الله تعالى والثناء عليه بما هو أهله.", "لا يصح حمد أحد بدون ما يوجد لديه من صفات الكمال ما يُحمد عليه.", "التعجب من حال من يسوّون المخلوقات بالخالق عز وجل في العبادة.", "التعجب من حال من يرى عجائب صنع الله ومظاهر قدرته ثم ينكر البعث والحياة الآخرة.", "صفة العلم لله تعالى، وأنه لا يخفى عليه شيء في الأرض ولا في السماء، يعلم السر وأخفى."], "k": "«الحمد لله الذي خلق السموات والأرض»… على أي نعمة من خلقه أحمده اليوم بقلب حاضر؟"}, {"lbl": "الآيات ٤ – ٦", "q": "وَمَا تَأۡتِيهِم مِّنۡ ءَايَةٖ مِّنۡ ءَايَٰتِ رَبِّهِمۡ إِلَّا كَانُواْ عَنۡهَا مُعۡرِضِينَ ﴿٤﴾ فَقَدۡ كَذَّبُواْ بِٱلۡحَقِّ لَمَّا جَآءَهُمۡ فَسَوۡفَ يَأۡتِيهِمۡ أَنۢبَـٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٥﴾ أَلَمۡ يَرَوۡاْ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنٖ مَّكَّنَّـٰهُمۡ فِي ٱلۡأَرۡضِ مَا لَمۡ نُمَكِّن لَّكُمۡ وَأَرۡسَلۡنَا ٱلسَّمَآءَ عَلَيۡهِم مِّدۡرَارٗا وَجَعَلۡنَا ٱلۡأَنۡهَٰرَ تَجۡرِي مِن تَحۡتِهِمۡ فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ ﴿٦﴾", "w": [["آية", "آيات القرآن الدالة على توحيد الله تعالى."], ["معرضين", "غير ملتفتين إليها ولا مفكّرين فيها."], ["الحق", "النبي ﷺ وما جاء به من الدين الحق."], ["أنباء", "أخبار ما كانوا به يستهزئون، وهو عذاب الدنيا وعذاب الآخرة."], ["من قرن", "أهل قرن من الأمم السابقة، والقرن: مائة سنة."], ["مكّنّاهم في الأرض", "أعطيناهم من القوة المادية ما لم نعطِ هؤلاء المشركين."], ["مدراراً", "مطراً متواصلاً غزيراً."], ["بذنوبهم", "بسبب ذنوبهم، وهي معصية الله ورسله."], ["وأنشأنا", "خلقنا بعد إهلاك الأولين."]], "m": "ما زال السياق في الذين يعدلون بربهم: ما تأتيهم من آية من آيات ربهم إلا قابلوها بالإعراض التام، وسبب ذلك أنهم كذّبوا بالحق لما جاءهم، وهو الرسول وما معه، فسوف يأتيهم أنباء ما كانوا به يستهزئون، وأول ذلك هزيمتهم يوم بدر، ثم القحط سبع سنين، ومن مات على الشرك فإلى نار جهنم. ألم يروا كم أهلكنا من قبلهم من قرن، مكّنّاهم في الأرض من الدولة والسلطان والمال ما لم نمكّن لكفار قريش، وأرسلنا السماء عليهم مدراراً، وجعلنا الأنهار تجري من تحت أشجارهم وقصورهم، فلما أنكروا التوحيد وكذّبوا الرسل أهلكناهم بذنوبهم، لا ظلماً منا، وأنشأنا من بعدهم قرناً آخرين، وكان ذلك علينا يسيراً.", "h": ["التكذيب بالحق هو سبب الإعراض عنه، فلو آمنوا به لأقبلوا عليه.", "الاستهزاء والسخرية بالدين من موجبات العذاب وقرب وقوعه.", "العبرة بهلاك الماضين ومصارع الظالمين.", "هلاك الأمم كان بسبب ذنوبهم، فما من مصيبة إلا بذنب."], "k": "«فأهلكناهم بذنوبهم»… هل أعدّ ذنوبي سبباً لما يصيبني من ضيق، فأتوب منها؟"}, {"lbl": "الآيات ٧ – ١١", "q": "وَلَوۡ نَزَّلۡنَا عَلَيۡكَ كِتَٰبٗا فِي قِرۡطَاسٖ فَلَمَسُوهُ بِأَيۡدِيهِمۡ لَقَالَ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ ﴿٧﴾ وَقَالُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ مَلَكٞۖ وَلَوۡ أَنزَلۡنَا مَلَكٗا لَّقُضِيَ ٱلۡأَمۡرُ ثُمَّ لَا يُنظَرُونَ ﴿٨﴾ وَلَوۡ جَعَلۡنَٰهُ مَلَكٗا لَّجَعَلۡنَٰهُ رَجُلٗا وَلَلَبَسۡنَا عَلَيۡهِم مَّا يَلۡبِسُونَ ﴿٩﴾ وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُواْ مِنۡهُم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿١٠﴾ قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ ثُمَّ ٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ ﴿١١﴾", "w": [["قرطاساً", "ما يُكتب عليه، جلداً كان أو ورقاً."], ["لمسوه بأيديهم", "مسّوه بأصابعهم ليتأكدوا منه."], ["ملَك", "أحد الملائكة."], ["لقُضي الأمر", "أُهلكوا وانتهت حياتهم."], ["ثم لا يُنظرون", "لا يُمهلون."], ["ولو جعلناه ملكاً", "ولو جعلنا الرسول إليهم ملكاً لإنكارهم البشر."], ["للبسنا", "لخلطنا عليهم."], ["استُهزئ", "سُخر به وتُهكّم."], ["حاق بهم", "نزل بهم العذاب وأحاط بهم فأُهلكوا."]], "m": "ما زال السياق في العادلين بربهم أصنامهم: ولو نزّلنا عليك كتاباً مكتوباً في ورق فرأوه منزلاً من السماء ولمسوه بأيديهم، ما آمنوا، ولقالوا: إن هذا إلا سحر مبين. وقالوا: لولا أُنزل عليه ملك يصدّقه، ولو أنزلنا ملكاً فكذّبوه لقُضي الأمر بإهلاكهم ثم لا يُمهلون ساعة ليتوبوا، إذ الملائكة لا تنزل إلا لإحقاق الحق. ولو جعلنا الرسول ملكاً لقالوا: كيف نفهم عن الملك ونحن بشر؟ فلجعلناه رجلاً، وللبسنا عليهم ما يلبسون. ثم سلّى رسوله: ولقد استُهزئ برسل من قبلك فاصبر، فحاق بالذين سخروا منهم ما كانوا به يستهزئون. ثم أمره أن يقول لأكابر مجرمي قريش: سيروا في الأرض، جنوباً إلى ديار عاد، أو شمالاً إلى ديار ثمود، أو غرباً إلى بحيرة لوط، ثم انظروا كيف كان عاقبة المكذبين، لعلكم تكفّون عن طغيانكم.", "h": ["الآيات بمعنى المعجزات والخوارق لا تستلزم الإيمان، بل قد تكون سبباً للكفر والعناد، ولذا لم يعطِ الله رسوله ما طالبت به قريش.", "إنكار رسالة البشر عام في كل الأمم، في حين أن إرسال الملائكة لا يتم معه هدف لعدم قدرة الإنسان على التلقّي عنهم.", "الاستهزاء بالرسل والدعاة سنة بشرية لا تكاد تتخلّف، ولذا وجب على الرسل والدعاة الصبر على ذلك.", "عاقبة التكذيب والاستهزاء هلاك المكذبين المستهزئين.", "مشروعية زيارة القبور للوقوف على مصير الإنسان ومآل أمره، فإن في ذلك ما يخفّف شهوة الدنيا والتكالب عليها، وهو سبب الظلم والفساد."], "k": "متى آخر مرة زرت المقابر، أو تأملت في آثار الماضين، فخفّت الدنيا في قلبي؟"}, {"lbl": "الآيات ١٢ – ١٦", "q": "قُل لِّمَن مَّا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُل لِّلَّهِۚ كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِۚ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فَهُمۡ لَا يُؤۡمِنُونَ ﴿١٢﴾ ۞وَلَهُۥ مَا سَكَنَ فِي ٱلَّيۡلِ وَٱلنَّهَارِۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿١٣﴾ قُلۡ أَغَيۡرَ ٱللَّهِ أَتَّخِذُ وَلِيّٗا فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَهُوَ يُطۡعِمُ وَلَا يُطۡعَمُۗ قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَكُونَ أَوَّلَ مَنۡ أَسۡلَمَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ ﴿١٤﴾ قُلۡ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ ﴿١٥﴾ مَّن يُصۡرَفۡ عَنۡهُ يَوۡمَئِذٖ فَقَدۡ رَحِمَهُۥۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡمُبِينُ ﴿١٦﴾", "w": [["لا ريب فيه", "لا شك في مجيئه وحصوله في أجله المحدد له."], ["خسروا أنفسهم", "لوّثوها بأوضار الشرك والمعاصي فلم ينتفعوا بها."], ["وله ما سكن في الليل والنهار", "ما استقر فيهما من ساكن ومتحرك، أي له كل شيء."], ["ولياً", "أحبه وأنصره، وأطلب نصرته ومحبته وولايته."], ["الفوز المبين", "الواضح، إذ النجاة من النار ودخول الجنة هو الفوز."]], "m": "ما زال السياق مع العادلين بربهم: قل لمن ما في السموات والأرض؟ واسبقهم إلى الجواب: قل لله، الذي كتب على نفسه الرحمة، ومظاهرها متجلّية: إنهم يكفرونه ويعصونه وهو يطعمهم ويسقيهم ويحفظهم، ومن رحمته جمعه الناس ليوم القيامة ليجزيهم، الحسنة بعشر أمثالها والسيئة بمثلها، ليجمعنّكم إلى يوم القيامة لا ريب فيه، الذين خسروا أنفسهم فهم لا يؤمنون. وله ما سكن في الليل والنهار، وهو السميع العليم، فوجب اللجوء إليه والتوكل عليه. ثم أمر رسوله أن يردّ على المشركين الذين طالبوه بموافقتهم على شركهم: أغير الله أتخذ ولياً، فاطر السموات والأرض، وهو يُطعم غيره لافتقارهم إليه ولا يُطعم لغناه المطلق؟ قل إني أُمرت أن أكون أول من أسلم، ولا تكوننّ من المشركين. قل إني أخاف إن عصيت ربي عذاب يوم عظيم، من يُصرف عنه يومئذ فقد رحمه، وذلك الفوز المبين.", "h": ["عموم رحمة الله تعالى.", "تقرير مبدأ الشقاوة والسعادة في الأزل قبل خلق الخلق.", "الله رب كل شيء ومليكه.", "تحريم ولاية غير الله، وتحريم الشرك به تعالى.", "بيان الفوز الأخروي، وهو النجاة من العذاب ودخول الجنة."], "k": "«كتب على نفسه الرحمة»… كم مرة عصيته فلم يقطع عني رزقه؟ أفلا يستحق مني الحياء؟"}, {"lbl": "الآيات ١٧ – ١٩", "q": "وَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرّٖ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن يَمۡسَسۡكَ بِخَيۡرٖ فَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿١٧﴾ وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ ﴿١٨﴾ قُلۡ أَيُّ شَيۡءٍ أَكۡبَرُ شَهَٰدَةٗۖ قُلِ ٱللَّهُۖ شَهِيدُۢ بَيۡنِي وَبَيۡنَكُمۡۚ وَأُوحِيَ إِلَيَّ هَٰذَا ٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۚ أَئِنَّكُمۡ لَتَشۡهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخۡرَىٰۚ قُل لَّآ أَشۡهَدُۚ قُلۡ إِنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ وَإِنَّنِي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ ﴿١٩﴾", "w": [["يمسسك", "يصبك."], ["بضرّ", "الضر: ما يؤلم الجسم أو النفس كالمرض والحزن."], ["بخير", "الخير: كل ما يُسعد الجسم أو الروح."], ["القاهر", "الغالب المذلّ المعزّ."], ["شهادة", "الشهادة: إخبار العالم بالشيء عنه بما لا يخالفه."], ["لأنذركم به", "لأخوّفكم بما فيه من وعيد الله لأهل عداوته."], ["إله واحد", "معبود واحد، لأنه رب واحد، إذ لا يُعبد إلا الرب الخالق الرازق المدبّر."]], "m": "ما زال السياق في تقوية موقف الرسول ﷺ من المشركين: وإن يمسسك الله بضرّ في بدنك فلا كاشف له إلا هو، وإن يمسسك بخير فهو على كل شيء قدير، فلا رادّ لفضله، والخطاب وإن كان للرسول فهو عام في كل أحد. وهو القاهر فوق عباده، وهو الحكيم الخبير، وقهره لكل أحد وعلوّه وعلمه موجب لألوهيته وبطلان عبادة غيره. ولما قال المشركون: ائتنا بمن يشهد لك بالنبوة، فإن أهل الكتاب أنكروها، أمره أن يقول: أي شيء أكبر شهادة؟ قل الله شهيد بيني وبينكم، وشهادته لي إيحاؤه إليّ هذا القرآن لأنذركم به ومن بلغ، فكل من بلغه ولم يؤمن به فهو خاسر. ثم أمره أن ينكر عليهم: أئنكم لتشهدون أن مع الله آلهة أخرى؟ قل لا أشهد، قل إنما هو إله واحد وإنني بريء مما تشركون.", "h": ["وجوب اللجوء إلى الله تعالى دون غيره من سائر خلقه، إذ لا يكشف الضر إلا هو.", "شهادة الله تعالى لرسوله بالنبوة، وما أنزل عليه من القرآن، وما أعطاه من المعجزات.", "نذارة الرسول ﷺ بلغت كل من بلغه القرآن الكريم إلى يوم الدين.", "تقرير مبدأ التوحيد: لا إله إلا الله، ووجوب البراءة من الشرك."], "k": "«وإن يمسسك الله بضرّ فلا كاشف له إلا هو»… إلى من ألجأ أولاً حين يصيبني همّ أو مرض؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (89, 6, 20, 45, 'سورة الأنعام ٢٠ – ٤٥', 'يعرفونه كما يعرفون أبناءهم، و«يا ليتنا نُرَدّ»، وتسلية النبي ﷺ', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 89) = $j$[{"lbl": "الآيات ٢٠ – ٢٤", "q": "ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمُۘ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فَهُمۡ لَا يُؤۡمِنُونَ ﴿٢٠﴾ وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّـٰلِمُونَ ﴿٢١﴾ وَيَوۡمَ نَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ نَقُولُ لِلَّذِينَ أَشۡرَكُوٓاْ أَيۡنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمۡ تَزۡعُمُونَ ﴿٢٢﴾ ثُمَّ لَمۡ تَكُن فِتۡنَتُهُمۡ إِلَّآ أَن قَالُواْ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشۡرِكِينَ ﴿٢٣﴾ ٱنظُرۡ كَيۡفَ كَذَبُواْ عَلَىٰٓ أَنفُسِهِمۡۚ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ ﴿٢٤﴾", "w": [["الذين آتيناهم الكتاب", "علماء اليهود والنصارى."], ["يعرفونه", "يعرفون محمداً ﷺ نبياً لله ورسولاً له."], ["افترى على الله كذباً", "اختلق الكذب وزوّره في نفسه وقاله."], ["لا يفلح الظالمون", "لا ينجون من عذاب الله يوم القيامة."], ["تزعمون", "تدّعون أنهم شركاء يشفعون لكم عند الله."], ["وضلّ عنهم", "غاب عنهم ولم يحضرهم ما كانوا يفترونه."]], "m": "الذين آتيناهم الكتاب من علماء اليهود والنصارى يعرفون محمداً ﷺ أنه نبي الله، وأن القرآن كتاب الله، بما ثبت عندهم من أخباره ونعوته، معرفةً كمعرفتهم أبناءهم، ردّاً على العرب الذين قالوا: لو كنت نبياً لشهد لك أهل الكتاب؛ الذين خسروا أنفسهم فهم لا يؤمنون، إيثاراً للدنيا على الآخرة. ومن أظلم ممن افترى على الله كذباً أو كذّب بآياته؟ إنه لا يفلح الظالمون. ويوم نحشرهم جميعاً نقول للذين أشركوا: أين شركاؤكم الذين كنتم تزعمون أنهم يشفعون لكم؟ ثم لم تكن نتيجة هذا الاختبار إلا أن قالوا: والله ربنا ما كنا مشركين، يكذبون لأنهم رأوا أن المشركين لا يُغفر لهم. انظر كيف كذبوا على أنفسهم، وضلّ عنهم ما كانوا يفترون.", "h": ["لم يمنع أهل الكتاب من الدخول في الإسلام إلا إيثار الدنيا على الآخرة.", "سببان في عظم الجريمة: الكذب على الله بالافتراء، والتكذيب الجاحد به وبكتابه ونبيه."], "k": "«والله ربنا ما كنا مشركين»… ماذا سأقول يوم القيامة إن سُئلت عما قدّمته على الله في قلبي؟"}, {"lbl": "الآيات ٢٥ – ٢٨", "q": "وَمِنۡهُم مَّن يَسۡتَمِعُ إِلَيۡكَۖ وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ وَإِن يَرَوۡاْ كُلَّ ءَايَةٖ لَّا يُؤۡمِنُواْ بِهَاۖ حَتَّىٰٓ إِذَا جَآءُوكَ يُجَٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ﴿٢٥﴾ وَهُمۡ يَنۡهَوۡنَ عَنۡهُ وَيَنۡـَٔوۡنَ عَنۡهُۖ وَإِن يُهۡلِكُونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ ﴿٢٦﴾ وَلَوۡ تَرَىٰٓ إِذۡ وُقِفُواْ عَلَى ٱلنَّارِ فَقَالُواْ يَٰلَيۡتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ ﴿٢٧﴾ بَلۡ بَدَا لَهُم مَّا كَانُواْ يُخۡفُونَ مِن قَبۡلُۖ وَلَوۡ رُدُّواْ لَعَادُواْ لِمَا نُهُواْ عَنۡهُ وَإِنَّهُمۡ لَكَٰذِبُونَ ﴿٢٨﴾", "w": [["أكنّة", "جمع كنان، ما يُكنّ فيه الشيء كالغطاء."], ["وقراً", "ثقلاً وصمماً فهم لا يسمعون."], ["يجادلونك", "يخاصمونك."], ["أساطير الأولين", "جمع أسطورة: ما يُكتب ويُحكى من أخبار السابقين."], ["وينأون عنه", "ويبعدون عنه."], ["بل بدا لهم", "بل ظهر لهم."]], "m": "ما زال السياق في المشركين: ومنهم من يستمع إليك حال قراءتك القرآن، ولكنه لا يعيه قلبه، لما جعلنا، حسب سنتنا، على قلوبهم أغطية وفي آذانهم صمماً، وهما نتيجة ما يحملونه من بغض للنبي ﷺ وكره للتوحيد، وإن يروا كل آية مما يطالبون به لا يؤمنوا بها لأنهم لا يريدون أن يؤمنوا، حتى إذا جاؤوك يجادلونك يقولون: ما هذا إلا أساطير الأولين. وهم ينهون الناس عن الإيمان به ومتابعته، ويبعدون هم عنه، وهذه شرّ الصفات، وما يُهلكون إلا أنفسهم وما يشعرون، إذ أفقدهم الشعورَ حبُّ الباطل. ولو ترى إذ وُقفوا على النار، فقالوا: يا ليتنا نُردّ إلى الدنيا ولا نكذّب بآيات ربنا ونكون من المؤمنين، وما هم بصادقين، وإنما حملهم على ذلك الخوف من العذاب، بل بدا لهم ما كانوا يخفون من قبل، ولو رُدّوا لعادوا لما نُهوا عنه وإنهم لكاذبون.", "h": ["بيان سنة الله تعالى في أن العبد إذا كره أحداً وأبغضه وتغالى في ذلك يصبح لا يسمع ما يقول له، ولا يفهم معنى ما يسمع منه.", "شرّ دعاة الشر من يُعرض عن الهدى ويأمر بالإعراض عنه، وينهى من يُقبل عليه.", "سبب الشر في الأرض: الكفر بالله، وإنكار البعث والجزاء الآخر."], "k": "«ولو رُدّوا لعادوا لما نُهوا عنه»… أنا الآن في الفرصة التي سيتمنّاها غيري، فماذا أصنع بها؟"}, {"lbl": "الآيات ٢٩ – ٣٢", "q": "وَقَالُوٓاْ إِنۡ هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا وَمَا نَحۡنُ بِمَبۡعُوثِينَ ﴿٢٩﴾ وَلَوۡ تَرَىٰٓ إِذۡ وُقِفُواْ عَلَىٰ رَبِّهِمۡۚ قَالَ أَلَيۡسَ هَٰذَا بِٱلۡحَقِّۚ قَالُواْ بَلَىٰ وَرَبِّنَاۚ قَالَ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ ﴿٣٠﴾ قَدۡ خَسِرَ ٱلَّذِينَ كَذَّبُواْ بِلِقَآءِ ٱللَّهِۖ حَتَّىٰٓ إِذَا جَآءَتۡهُمُ ٱلسَّاعَةُ بَغۡتَةٗ قَالُواْ يَٰحَسۡرَتَنَا عَلَىٰ مَا فَرَّطۡنَا فِيهَا وَهُمۡ يَحۡمِلُونَ أَوۡزَارَهُمۡ عَلَىٰ ظُهُورِهِمۡۚ أَلَا سَآءَ مَا يَزِرُونَ ﴿٣١﴾ وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَعِبٞ وَلَهۡوٞۖ وَلَلدَّارُ ٱلۡأٓخِرَةُ خَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ ﴿٣٢﴾", "w": [["وُقفوا على ربهم", "جيء بهم ووُقفوا على قضائه وحكمه فيهم."], ["بلى وربنا", "إنه للحق والله."], ["خسر الذين كذّبوا", "خسروا أنفسهم في جهنم."], ["الساعة بغتة", "الساعة: البعث ليوم القيامة، وبغتة: فجأة."], ["يا حسرتنا", "الحسرة: التندّم والتحسّر على ما فات، ينادون حسرتهم زيادةً في التألّم."], ["أوزارهم", "أحمال ذنوبهم، إذ الوزر الحمل الثقيل."], ["لعب ولهو", "اللعب: العمل الذي لا يجلب درهماً للمعاش ولا حسنة للمعاد، واللهو: ما يشغل الإنسان عما يعنيه."]], "m": "وقالوا: إن هي إلا حياتنا الدنيا وما نحن بمبعوثين؛ وهذا سبب بلائهم وجرأتهم على الشرك ومحاربة الموحّدين. ولو تراهم وقد حُبسوا لقضاء الله، وقيل لهم وهم يشاهدون أهوال القيامة: أليس هذا بالحق الذي كنتم تكذّبون؟ قالوا: بلى وربنا، قال: فذوقوا العذاب بما كنتم تكفرون، لا ظلماً منا. قد خسر الذين كذّبوا بلقاء الله، وباعوا الإيمان بالكفر، حتى إذا جاءتهم الساعة بغتة قالوا: يا حسرتنا على ما فرّطنا فيها، وهم يحملون أوزارهم على ظهورهم، ألا ساء ما يزرون. ثم وعظ عباده: وما الحياة الدنيا إلا لعب ولهو، فلا تغترّوا بملذّاتها فإنها إلى زوال، وللدار الآخرة خير للذين يتقون الشرك والمعاصي، أفلا تعقلون؟", "h": ["تقرير مبدأ البعث والجزاء بذكر صور ومشاهد له.", "قبح الذنوب، وأنها أسوأ حمل يحمله صاحبها يوم القيامة.", "حكم الله تعالى بالخسران على من كذّب بلقائه فلم يؤمن ولم يعمل صالحاً.", "الساعة لا تأتي إلا بغتة، ولا ينافي ذلك ظهور علاماتها، لأن الزمن ما بين العلامة والعلامة لا يُعرف مقداره.", "نصيحة القرآن للعقلاء ألا يغترّوا بالحياة الدنيا ويُهملوا شأن الآخرة وهي خير."], "k": "«يا حسرتنا على ما فرّطنا فيها»… ما الذي أخشى أن أتحسّر على تفريطي فيه، فأتداركه اليوم؟"}, {"lbl": "الآيات ٣٣ – ٣٥", "q": "قَدۡ نَعۡلَمُ إِنَّهُۥ لَيَحۡزُنُكَ ٱلَّذِي يَقُولُونَۖ فَإِنَّهُمۡ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ ٱلظَّـٰلِمِينَ بِـَٔايَٰتِ ٱللَّهِ يَجۡحَدُونَ ﴿٣٣﴾ وَلَقَدۡ كُذِّبَتۡ رُسُلٞ مِّن قَبۡلِكَ فَصَبَرُواْ عَلَىٰ مَا كُذِّبُواْ وَأُوذُواْ حَتَّىٰٓ أَتَىٰهُمۡ نَصۡرُنَاۚ وَلَا مُبَدِّلَ لِكَلِمَٰتِ ٱللَّهِۚ وَلَقَدۡ جَآءَكَ مِن نَّبَإِيْ ٱلۡمُرۡسَلِينَ ﴿٣٤﴾ وَإِن كَانَ كَبُرَ عَلَيۡكَ إِعۡرَاضُهُمۡ فَإِنِ ٱسۡتَطَعۡتَ أَن تَبۡتَغِيَ نَفَقٗا فِي ٱلۡأَرۡضِ أَوۡ سُلَّمٗا فِي ٱلسَّمَآءِ فَتَأۡتِيَهُم بِـَٔايَةٖۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَمَعَهُمۡ عَلَى ٱلۡهُدَىٰۚ فَلَا تَكُونَنَّ مِنَ ٱلۡجَٰهِلِينَ ﴿٣٥﴾", "w": [["ليحزنك", "ليوقعك في الحزن، وهو ألم النفس من فقد ما تحب."], ["فإنهم لا يكذّبونك", "لا ينسبونك إلى الكذب في بواطنهم ومجالسهم السرية، لعلمهم اليقيني أنك صادق."], ["كُذّبت رسل", "كذّبتهم أممهم كنوح وإبراهيم وموسى وعيسى ﵈."], ["ولا مبدّل لكلمات الله", "التي تحمل وعده بنصر أوليائه وإهلاك أعدائه."], ["من نبأ المرسلين", "أخبارهم في دعواتهم مع أممهم."], ["تبتغي نفقاً", "تطلب سرباً تحت الأرض."], ["أو سلّماً في السماء", "مصعداً تصعد به إلى السماء."], ["بآية", "خارقة من خوارق العادات."], ["فلا تكوننّ من الجاهلين", "فلا تقف موقف الجاهلين بتدبير الله في خلقه."]], "m": "هذه الآيات من تربية الله لرسوله ﷺ لما يشدّ عزمه: قد نعلم إنه ليحزنك الذي يقولون من تكذيبك واتهامك بالسحر، فإنهم لا يكذّبونك في الحقيقة، وهم كانوا يلقّبونك قبل البعثة بالأمين، ولكن الظالمين بآيات الله يجحدون، إبقاءً على عاداتهم وأوثانهم، فلا تحزن. ولقد كُذّبت رسل من قبلك فصبروا على ما كُذّبوا وأوذوا حتى أتاهم نصرنا، فاصبر حتى يأتيك النصر، ولا مبدّل لكلمات الله، ولقد جاءك من نبأ المرسلين ما يعينك على الصبر. وإن كان كبُر عليك إعراضهم حتى تأتيهم بآية كما يطلبون، فإن استطعت أن تبتغي نفقاً في الأرض أو سلّماً في السماء فتأتيهم بآية فافعل، وما أنت بقادر، فاصبر. ولو شاء الله لجمعهم على الهدى، ولكنه لم يشأ لحكم عالية، فلا تطلب ما لا يريده ربك فتكون من الجاهلين.", "h": ["ثبوت بشرية الرسول ﷺ، ولذا هو يحزن لفوت محبوب كما يحزن البشر.", "تسلية الرسول ﷺ، وحمله على الصبر حتى يأتيه موعود ربه بالنصر.", "بيان سنة الله في الأمم السابقة.", "إرشاد الرب تعالى رسوله إلى خير المقامات وأكمل الحالات بإبعاده عن ساحة الجاهلين."], "k": "«قد نعلم إنه ليحزنك»… ربي يعلم حزني حين يُساء إليّ، فهل يكفيني علمه فأصبر؟"}, {"lbl": "الآيات ٣٦ – ٣٩", "q": "۞إِنَّمَا يَسۡتَجِيبُ ٱلَّذِينَ يَسۡمَعُونَۘ وَٱلۡمَوۡتَىٰ يَبۡعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيۡهِ يُرۡجَعُونَ ﴿٣٦﴾ وَقَالُواْ لَوۡلَا نُزِّلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةٗ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿٣٧﴾ وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ وَلَا طَـٰٓئِرٖ يَطِيرُ بِجَنَاحَيۡهِ إِلَّآ أُمَمٌ أَمۡثَالُكُمۚ مَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءٖۚ ثُمَّ إِلَىٰ رَبِّهِمۡ يُحۡشَرُونَ ﴿٣٨﴾ وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا صُمّٞ وَبُكۡمٞ فِي ٱلظُّلُمَٰتِۗ مَن يَشَإِ ٱللَّهُ يُضۡلِلۡهُ وَمَن يَشَأۡ يَجۡعَلۡهُ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٣٩﴾", "w": [["إنما يستجيب", "لدعوة الحق التي دعا بها رسول الله ﷺ فيؤمن ويهتدي."], ["يبعثهم الله", "يوم القيامة."], ["لولا نُزّل عليه آية", "«لولا» أداة تحضيض بمعنى هلّا."], ["آية من ربه", "خارقة تكون علامة على صدقه."], ["لا يعلمون", "ما يترتب على إيتائها مع عدم الإيمان بعدها من هلاك."], ["من دابّة", "الدابة: كل ما يدبّ على الأرض من إنسان وحيوان."], ["في الكتاب", "كتاب المقادير، اللوح المحفوظ."], ["صمّ وبكم في الظلمات", "صمّ لا يسمعون، وبكم لا ينطقون، في الظلمات لا يبصرون."], ["صراط مستقيم", "الدين الإسلامي المفضي بالآخذ به إلى سعادة الدارين."]], "m": "بعد أن سلّى الله رسوله، أعلمه بحقيقة تعينه على الثبات: إنما يستجيب لدعوتك الذين يسمعون، لسلامة حاسة السمع عندهم من كره الحق، والموتى، وهم الكفار لموت قلوبهم، يبعثهم الله ثم إليه يُرجعون فيجزيهم. وقالوا: لولا نُزّل عليه آية من ربه، قل إن الله قادر على أن ينزّل آية، كإحياء الموتى أو إنزال الملائكة عياناً، ولكن أكثرهم لا يعلمون أنها لو نزلت ثم لم يؤمنوا كانت نهايتهم. وما من دابة في الأرض ولا طائر يطير بجناحيه إلا أمم أمثالكم، مفتقرة إلى الله في خلقها ورزقها وتدبير حياتها، يُحصي عملها ثم يبعثها، ما فرّطنا في الكتاب من شيء، فهل يُعقل أن يعجز عن إنزال آية؟ ثم إلى ربهم يُحشرون. والذين كذّبوا بآياتنا صمّ وبكم في الظلمات، أموات غير أحياء، من يشأ الله يضلله ومن يشأ يجعله على صراط مستقيم، فمن أراد الهداية فليطلبها بصدق من الله.", "h": ["الإيمان بالله ورسوله ولقائه حياة، والكفر بذلك موت؛ فالمؤمن حي والكافر ميت.", "سبب تأخّر الآيات علم الله تعالى بأنه لو أعطاهم الآيات ما آمنوا، وبذلك يستوجبون الهلاك.", "تعدّد الأمم في الأرض وتعدّد أجناسها، والكل خاضع لتدبير الله تعالى مربوب له.", "تقرير ركن القضاء والقدر، وإثباته في أم الكتاب."], "k": "«إلا أمم أمثالكم»… هل أرحم ما حولي من الخلق، وأعلم أن ربي يرزقهم ويحصيهم كما يحصيني؟"}, {"lbl": "الآيات ٤٠ – ٤٥", "q": "قُلۡ أَرَءَيۡتَكُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُ ٱللَّهِ أَوۡ أَتَتۡكُمُ ٱلسَّاعَةُ أَغَيۡرَ ٱللَّهِ تَدۡعُونَ إِن كُنتُمۡ صَٰدِقِينَ ﴿٤٠﴾ بَلۡ إِيَّاهُ تَدۡعُونَ فَيَكۡشِفُ مَا تَدۡعُونَ إِلَيۡهِ إِن شَآءَ وَتَنسَوۡنَ مَا تُشۡرِكُونَ ﴿٤١﴾ وَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَأَخَذۡنَٰهُم بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَتَضَرَّعُونَ ﴿٤٢﴾ فَلَوۡلَآ إِذۡ جَآءَهُم بَأۡسُنَا تَضَرَّعُواْ وَلَٰكِن قَسَتۡ قُلُوبُهُمۡ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ مَا كَانُواْ يَعۡمَلُونَ ﴿٤٣﴾ فَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦ فَتَحۡنَا عَلَيۡهِمۡ أَبۡوَٰبَ كُلِّ شَيۡءٍ حَتَّىٰٓ إِذَا فَرِحُواْ بِمَآ أُوتُوٓاْ أَخَذۡنَٰهُم بَغۡتَةٗ فَإِذَا هُم مُّبۡلِسُونَ ﴿٤٤﴾ فَقُطِعَ دَابِرُ ٱلۡقَوۡمِ ٱلَّذِينَ ظَلَمُواْۚ وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴿٤٥﴾", "w": [["أرأيتكم", "أخبروني."], ["الساعة", "يوم القيامة."], ["يكشف", "يزيل ويُبعد ويُنجي."], ["يتضرّعون", "يتذلّلون في الدعاء خاضعين."], ["بغتة", "فجأة وعلى حين غفلة."], ["مبلسون", "آيسون قانطون متحسّرون."], ["دابر القوم", "آخرهم، أي أُهلكوا من أولهم إلى آخرهم."], ["الحمد لله", "الثناء بالجميل والشكر لله دون سواه."]], "m": "ما زال السياق في هداية المشركين: قل أخبروني إن أتاكم عذاب الله اليوم، أو أتتكم الساعة، أغير الله تدعون ليصرفه عنكم إن كنتم صادقين؟ بل إياه تدعون فيكشف ما تدعون إليه إن شاء، وتنسون ما تشركون، ليأسكم من إجابتها. ثم أخبر رسوله: ولقد أرسلنا إلى أمم من قبلك رسلاً فكذّبوهم، فأخذناهم بالبأساء والضراء من حروب ومجاعات وأمراض لعلهم يتضرّعون فيرجعون، فلولا إذ جاءهم بأسنا تضرّعوا، ولكن قست قلوبهم وزيّن لهم الشيطان ما كانوا يعملون. فلما نسوا ما ذُكّروا به فتحنا عليهم أبواب كل شيء من الخيرات استدراجاً، حتى إذا فرحوا بما أوتوا واطمأنّوا أخذناهم بغتة فإذا هم آيسون متحسّرون، فقُطع دابر القوم الذين ظلموا، والحمد لله رب العالمين، ناصر أوليائه ومهلك أعدائه.", "h": ["من غريب أحوال الإنسان المشرك أنه في حال الشدة الحقيقية يدعو الله وحده، ولا يدعو معه الآلهة الباطلة التي كان يدعوها في حال الرخاء.", "بيان سنة الله تعالى في إهلاك الأمم.", "إذا رأيت الأمة قد فسقت عن أمر ربها فعوقبت فلم تتّعظ، واستمرت على فسقها، وبسط الله لها في الرزق، فاعلم أنها قد استُدرجت للهلاك.", "شؤم الظلم هلاك الظالمين.", "الإرشاد إلى حمد الله تعالى عند نهاية كل عمل."], "k": "«فتحنا عليهم أبواب كل شيء»… هل النعم التي عندي تقرّبني من ربي، أم أنا مُستدرَج بها وأنا لا أشعر؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 89;
insert into public.tdb_cards(topic, i, body) select 89, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٠ – ٢٤", "q": "ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمُۘ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فَهُمۡ لَا يُؤۡمِنُونَ ﴿٢٠﴾ وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّـٰلِمُونَ ﴿٢١﴾ وَيَوۡمَ نَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ نَقُولُ لِلَّذِينَ أَشۡرَكُوٓاْ أَيۡنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمۡ تَزۡعُمُونَ ﴿٢٢﴾ ثُمَّ لَمۡ تَكُن فِتۡنَتُهُمۡ إِلَّآ أَن قَالُواْ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشۡرِكِينَ ﴿٢٣﴾ ٱنظُرۡ كَيۡفَ كَذَبُواْ عَلَىٰٓ أَنفُسِهِمۡۚ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ ﴿٢٤﴾", "w": [["الذين آتيناهم الكتاب", "علماء اليهود والنصارى."], ["يعرفونه", "يعرفون محمداً ﷺ نبياً لله ورسولاً له."], ["افترى على الله كذباً", "اختلق الكذب وزوّره في نفسه وقاله."], ["لا يفلح الظالمون", "لا ينجون من عذاب الله يوم القيامة."], ["تزعمون", "تدّعون أنهم شركاء يشفعون لكم عند الله."], ["وضلّ عنهم", "غاب عنهم ولم يحضرهم ما كانوا يفترونه."]], "m": "الذين آتيناهم الكتاب من علماء اليهود والنصارى يعرفون محمداً ﷺ أنه نبي الله، وأن القرآن كتاب الله، بما ثبت عندهم من أخباره ونعوته، معرفةً كمعرفتهم أبناءهم، ردّاً على العرب الذين قالوا: لو كنت نبياً لشهد لك أهل الكتاب؛ الذين خسروا أنفسهم فهم لا يؤمنون، إيثاراً للدنيا على الآخرة. ومن أظلم ممن افترى على الله كذباً أو كذّب بآياته؟ إنه لا يفلح الظالمون. ويوم نحشرهم جميعاً نقول للذين أشركوا: أين شركاؤكم الذين كنتم تزعمون أنهم يشفعون لكم؟ ثم لم تكن نتيجة هذا الاختبار إلا أن قالوا: والله ربنا ما كنا مشركين، يكذبون لأنهم رأوا أن المشركين لا يُغفر لهم. انظر كيف كذبوا على أنفسهم، وضلّ عنهم ما كانوا يفترون.", "h": ["لم يمنع أهل الكتاب من الدخول في الإسلام إلا إيثار الدنيا على الآخرة.", "سببان في عظم الجريمة: الكذب على الله بالافتراء، والتكذيب الجاحد به وبكتابه ونبيه."], "k": "«والله ربنا ما كنا مشركين»… ماذا سأقول يوم القيامة إن سُئلت عما قدّمته على الله في قلبي؟"}, {"lbl": "الآيات ٢٥ – ٢٨", "q": "وَمِنۡهُم مَّن يَسۡتَمِعُ إِلَيۡكَۖ وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ وَإِن يَرَوۡاْ كُلَّ ءَايَةٖ لَّا يُؤۡمِنُواْ بِهَاۖ حَتَّىٰٓ إِذَا جَآءُوكَ يُجَٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ﴿٢٥﴾ وَهُمۡ يَنۡهَوۡنَ عَنۡهُ وَيَنۡـَٔوۡنَ عَنۡهُۖ وَإِن يُهۡلِكُونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ ﴿٢٦﴾ وَلَوۡ تَرَىٰٓ إِذۡ وُقِفُواْ عَلَى ٱلنَّارِ فَقَالُواْ يَٰلَيۡتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ ﴿٢٧﴾ بَلۡ بَدَا لَهُم مَّا كَانُواْ يُخۡفُونَ مِن قَبۡلُۖ وَلَوۡ رُدُّواْ لَعَادُواْ لِمَا نُهُواْ عَنۡهُ وَإِنَّهُمۡ لَكَٰذِبُونَ ﴿٢٨﴾", "w": [["أكنّة", "جمع كنان، ما يُكنّ فيه الشيء كالغطاء."], ["وقراً", "ثقلاً وصمماً فهم لا يسمعون."], ["يجادلونك", "يخاصمونك."], ["أساطير الأولين", "جمع أسطورة: ما يُكتب ويُحكى من أخبار السابقين."], ["وينأون عنه", "ويبعدون عنه."], ["بل بدا لهم", "بل ظهر لهم."]], "m": "ما زال السياق في المشركين: ومنهم من يستمع إليك حال قراءتك القرآن، ولكنه لا يعيه قلبه، لما جعلنا، حسب سنتنا، على قلوبهم أغطية وفي آذانهم صمماً، وهما نتيجة ما يحملونه من بغض للنبي ﷺ وكره للتوحيد، وإن يروا كل آية مما يطالبون به لا يؤمنوا بها لأنهم لا يريدون أن يؤمنوا، حتى إذا جاؤوك يجادلونك يقولون: ما هذا إلا أساطير الأولين. وهم ينهون الناس عن الإيمان به ومتابعته، ويبعدون هم عنه، وهذه شرّ الصفات، وما يُهلكون إلا أنفسهم وما يشعرون، إذ أفقدهم الشعورَ حبُّ الباطل. ولو ترى إذ وُقفوا على النار، فقالوا: يا ليتنا نُردّ إلى الدنيا ولا نكذّب بآيات ربنا ونكون من المؤمنين، وما هم بصادقين، وإنما حملهم على ذلك الخوف من العذاب، بل بدا لهم ما كانوا يخفون من قبل، ولو رُدّوا لعادوا لما نُهوا عنه وإنهم لكاذبون.", "h": ["بيان سنة الله تعالى في أن العبد إذا كره أحداً وأبغضه وتغالى في ذلك يصبح لا يسمع ما يقول له، ولا يفهم معنى ما يسمع منه.", "شرّ دعاة الشر من يُعرض عن الهدى ويأمر بالإعراض عنه، وينهى من يُقبل عليه.", "سبب الشر في الأرض: الكفر بالله، وإنكار البعث والجزاء الآخر."], "k": "«ولو رُدّوا لعادوا لما نُهوا عنه»… أنا الآن في الفرصة التي سيتمنّاها غيري، فماذا أصنع بها؟"}, {"lbl": "الآيات ٢٩ – ٣٢", "q": "وَقَالُوٓاْ إِنۡ هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا وَمَا نَحۡنُ بِمَبۡعُوثِينَ ﴿٢٩﴾ وَلَوۡ تَرَىٰٓ إِذۡ وُقِفُواْ عَلَىٰ رَبِّهِمۡۚ قَالَ أَلَيۡسَ هَٰذَا بِٱلۡحَقِّۚ قَالُواْ بَلَىٰ وَرَبِّنَاۚ قَالَ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ ﴿٣٠﴾ قَدۡ خَسِرَ ٱلَّذِينَ كَذَّبُواْ بِلِقَآءِ ٱللَّهِۖ حَتَّىٰٓ إِذَا جَآءَتۡهُمُ ٱلسَّاعَةُ بَغۡتَةٗ قَالُواْ يَٰحَسۡرَتَنَا عَلَىٰ مَا فَرَّطۡنَا فِيهَا وَهُمۡ يَحۡمِلُونَ أَوۡزَارَهُمۡ عَلَىٰ ظُهُورِهِمۡۚ أَلَا سَآءَ مَا يَزِرُونَ ﴿٣١﴾ وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَعِبٞ وَلَهۡوٞۖ وَلَلدَّارُ ٱلۡأٓخِرَةُ خَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ ﴿٣٢﴾", "w": [["وُقفوا على ربهم", "جيء بهم ووُقفوا على قضائه وحكمه فيهم."], ["بلى وربنا", "إنه للحق والله."], ["خسر الذين كذّبوا", "خسروا أنفسهم في جهنم."], ["الساعة بغتة", "الساعة: البعث ليوم القيامة، وبغتة: فجأة."], ["يا حسرتنا", "الحسرة: التندّم والتحسّر على ما فات، ينادون حسرتهم زيادةً في التألّم."], ["أوزارهم", "أحمال ذنوبهم، إذ الوزر الحمل الثقيل."], ["لعب ولهو", "اللعب: العمل الذي لا يجلب درهماً للمعاش ولا حسنة للمعاد، واللهو: ما يشغل الإنسان عما يعنيه."]], "m": "وقالوا: إن هي إلا حياتنا الدنيا وما نحن بمبعوثين؛ وهذا سبب بلائهم وجرأتهم على الشرك ومحاربة الموحّدين. ولو تراهم وقد حُبسوا لقضاء الله، وقيل لهم وهم يشاهدون أهوال القيامة: أليس هذا بالحق الذي كنتم تكذّبون؟ قالوا: بلى وربنا، قال: فذوقوا العذاب بما كنتم تكفرون، لا ظلماً منا. قد خسر الذين كذّبوا بلقاء الله، وباعوا الإيمان بالكفر، حتى إذا جاءتهم الساعة بغتة قالوا: يا حسرتنا على ما فرّطنا فيها، وهم يحملون أوزارهم على ظهورهم، ألا ساء ما يزرون. ثم وعظ عباده: وما الحياة الدنيا إلا لعب ولهو، فلا تغترّوا بملذّاتها فإنها إلى زوال، وللدار الآخرة خير للذين يتقون الشرك والمعاصي، أفلا تعقلون؟", "h": ["تقرير مبدأ البعث والجزاء بذكر صور ومشاهد له.", "قبح الذنوب، وأنها أسوأ حمل يحمله صاحبها يوم القيامة.", "حكم الله تعالى بالخسران على من كذّب بلقائه فلم يؤمن ولم يعمل صالحاً.", "الساعة لا تأتي إلا بغتة، ولا ينافي ذلك ظهور علاماتها، لأن الزمن ما بين العلامة والعلامة لا يُعرف مقداره.", "نصيحة القرآن للعقلاء ألا يغترّوا بالحياة الدنيا ويُهملوا شأن الآخرة وهي خير."], "k": "«يا حسرتنا على ما فرّطنا فيها»… ما الذي أخشى أن أتحسّر على تفريطي فيه، فأتداركه اليوم؟"}, {"lbl": "الآيات ٣٣ – ٣٥", "q": "قَدۡ نَعۡلَمُ إِنَّهُۥ لَيَحۡزُنُكَ ٱلَّذِي يَقُولُونَۖ فَإِنَّهُمۡ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ ٱلظَّـٰلِمِينَ بِـَٔايَٰتِ ٱللَّهِ يَجۡحَدُونَ ﴿٣٣﴾ وَلَقَدۡ كُذِّبَتۡ رُسُلٞ مِّن قَبۡلِكَ فَصَبَرُواْ عَلَىٰ مَا كُذِّبُواْ وَأُوذُواْ حَتَّىٰٓ أَتَىٰهُمۡ نَصۡرُنَاۚ وَلَا مُبَدِّلَ لِكَلِمَٰتِ ٱللَّهِۚ وَلَقَدۡ جَآءَكَ مِن نَّبَإِيْ ٱلۡمُرۡسَلِينَ ﴿٣٤﴾ وَإِن كَانَ كَبُرَ عَلَيۡكَ إِعۡرَاضُهُمۡ فَإِنِ ٱسۡتَطَعۡتَ أَن تَبۡتَغِيَ نَفَقٗا فِي ٱلۡأَرۡضِ أَوۡ سُلَّمٗا فِي ٱلسَّمَآءِ فَتَأۡتِيَهُم بِـَٔايَةٖۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَمَعَهُمۡ عَلَى ٱلۡهُدَىٰۚ فَلَا تَكُونَنَّ مِنَ ٱلۡجَٰهِلِينَ ﴿٣٥﴾", "w": [["ليحزنك", "ليوقعك في الحزن، وهو ألم النفس من فقد ما تحب."], ["فإنهم لا يكذّبونك", "لا ينسبونك إلى الكذب في بواطنهم ومجالسهم السرية، لعلمهم اليقيني أنك صادق."], ["كُذّبت رسل", "كذّبتهم أممهم كنوح وإبراهيم وموسى وعيسى ﵈."], ["ولا مبدّل لكلمات الله", "التي تحمل وعده بنصر أوليائه وإهلاك أعدائه."], ["من نبأ المرسلين", "أخبارهم في دعواتهم مع أممهم."], ["تبتغي نفقاً", "تطلب سرباً تحت الأرض."], ["أو سلّماً في السماء", "مصعداً تصعد به إلى السماء."], ["بآية", "خارقة من خوارق العادات."], ["فلا تكوننّ من الجاهلين", "فلا تقف موقف الجاهلين بتدبير الله في خلقه."]], "m": "هذه الآيات من تربية الله لرسوله ﷺ لما يشدّ عزمه: قد نعلم إنه ليحزنك الذي يقولون من تكذيبك واتهامك بالسحر، فإنهم لا يكذّبونك في الحقيقة، وهم كانوا يلقّبونك قبل البعثة بالأمين، ولكن الظالمين بآيات الله يجحدون، إبقاءً على عاداتهم وأوثانهم، فلا تحزن. ولقد كُذّبت رسل من قبلك فصبروا على ما كُذّبوا وأوذوا حتى أتاهم نصرنا، فاصبر حتى يأتيك النصر، ولا مبدّل لكلمات الله، ولقد جاءك من نبأ المرسلين ما يعينك على الصبر. وإن كان كبُر عليك إعراضهم حتى تأتيهم بآية كما يطلبون، فإن استطعت أن تبتغي نفقاً في الأرض أو سلّماً في السماء فتأتيهم بآية فافعل، وما أنت بقادر، فاصبر. ولو شاء الله لجمعهم على الهدى، ولكنه لم يشأ لحكم عالية، فلا تطلب ما لا يريده ربك فتكون من الجاهلين.", "h": ["ثبوت بشرية الرسول ﷺ، ولذا هو يحزن لفوت محبوب كما يحزن البشر.", "تسلية الرسول ﷺ، وحمله على الصبر حتى يأتيه موعود ربه بالنصر.", "بيان سنة الله في الأمم السابقة.", "إرشاد الرب تعالى رسوله إلى خير المقامات وأكمل الحالات بإبعاده عن ساحة الجاهلين."], "k": "«قد نعلم إنه ليحزنك»… ربي يعلم حزني حين يُساء إليّ، فهل يكفيني علمه فأصبر؟"}, {"lbl": "الآيات ٣٦ – ٣٩", "q": "۞إِنَّمَا يَسۡتَجِيبُ ٱلَّذِينَ يَسۡمَعُونَۘ وَٱلۡمَوۡتَىٰ يَبۡعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيۡهِ يُرۡجَعُونَ ﴿٣٦﴾ وَقَالُواْ لَوۡلَا نُزِّلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةٗ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿٣٧﴾ وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ وَلَا طَـٰٓئِرٖ يَطِيرُ بِجَنَاحَيۡهِ إِلَّآ أُمَمٌ أَمۡثَالُكُمۚ مَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءٖۚ ثُمَّ إِلَىٰ رَبِّهِمۡ يُحۡشَرُونَ ﴿٣٨﴾ وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا صُمّٞ وَبُكۡمٞ فِي ٱلظُّلُمَٰتِۗ مَن يَشَإِ ٱللَّهُ يُضۡلِلۡهُ وَمَن يَشَأۡ يَجۡعَلۡهُ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٣٩﴾", "w": [["إنما يستجيب", "لدعوة الحق التي دعا بها رسول الله ﷺ فيؤمن ويهتدي."], ["يبعثهم الله", "يوم القيامة."], ["لولا نُزّل عليه آية", "«لولا» أداة تحضيض بمعنى هلّا."], ["آية من ربه", "خارقة تكون علامة على صدقه."], ["لا يعلمون", "ما يترتب على إيتائها مع عدم الإيمان بعدها من هلاك."], ["من دابّة", "الدابة: كل ما يدبّ على الأرض من إنسان وحيوان."], ["في الكتاب", "كتاب المقادير، اللوح المحفوظ."], ["صمّ وبكم في الظلمات", "صمّ لا يسمعون، وبكم لا ينطقون، في الظلمات لا يبصرون."], ["صراط مستقيم", "الدين الإسلامي المفضي بالآخذ به إلى سعادة الدارين."]], "m": "بعد أن سلّى الله رسوله، أعلمه بحقيقة تعينه على الثبات: إنما يستجيب لدعوتك الذين يسمعون، لسلامة حاسة السمع عندهم من كره الحق، والموتى، وهم الكفار لموت قلوبهم، يبعثهم الله ثم إليه يُرجعون فيجزيهم. وقالوا: لولا نُزّل عليه آية من ربه، قل إن الله قادر على أن ينزّل آية، كإحياء الموتى أو إنزال الملائكة عياناً، ولكن أكثرهم لا يعلمون أنها لو نزلت ثم لم يؤمنوا كانت نهايتهم. وما من دابة في الأرض ولا طائر يطير بجناحيه إلا أمم أمثالكم، مفتقرة إلى الله في خلقها ورزقها وتدبير حياتها، يُحصي عملها ثم يبعثها، ما فرّطنا في الكتاب من شيء، فهل يُعقل أن يعجز عن إنزال آية؟ ثم إلى ربهم يُحشرون. والذين كذّبوا بآياتنا صمّ وبكم في الظلمات، أموات غير أحياء، من يشأ الله يضلله ومن يشأ يجعله على صراط مستقيم، فمن أراد الهداية فليطلبها بصدق من الله.", "h": ["الإيمان بالله ورسوله ولقائه حياة، والكفر بذلك موت؛ فالمؤمن حي والكافر ميت.", "سبب تأخّر الآيات علم الله تعالى بأنه لو أعطاهم الآيات ما آمنوا، وبذلك يستوجبون الهلاك.", "تعدّد الأمم في الأرض وتعدّد أجناسها، والكل خاضع لتدبير الله تعالى مربوب له.", "تقرير ركن القضاء والقدر، وإثباته في أم الكتاب."], "k": "«إلا أمم أمثالكم»… هل أرحم ما حولي من الخلق، وأعلم أن ربي يرزقهم ويحصيهم كما يحصيني؟"}, {"lbl": "الآيات ٤٠ – ٤٥", "q": "قُلۡ أَرَءَيۡتَكُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُ ٱللَّهِ أَوۡ أَتَتۡكُمُ ٱلسَّاعَةُ أَغَيۡرَ ٱللَّهِ تَدۡعُونَ إِن كُنتُمۡ صَٰدِقِينَ ﴿٤٠﴾ بَلۡ إِيَّاهُ تَدۡعُونَ فَيَكۡشِفُ مَا تَدۡعُونَ إِلَيۡهِ إِن شَآءَ وَتَنسَوۡنَ مَا تُشۡرِكُونَ ﴿٤١﴾ وَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَأَخَذۡنَٰهُم بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَتَضَرَّعُونَ ﴿٤٢﴾ فَلَوۡلَآ إِذۡ جَآءَهُم بَأۡسُنَا تَضَرَّعُواْ وَلَٰكِن قَسَتۡ قُلُوبُهُمۡ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ مَا كَانُواْ يَعۡمَلُونَ ﴿٤٣﴾ فَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦ فَتَحۡنَا عَلَيۡهِمۡ أَبۡوَٰبَ كُلِّ شَيۡءٍ حَتَّىٰٓ إِذَا فَرِحُواْ بِمَآ أُوتُوٓاْ أَخَذۡنَٰهُم بَغۡتَةٗ فَإِذَا هُم مُّبۡلِسُونَ ﴿٤٤﴾ فَقُطِعَ دَابِرُ ٱلۡقَوۡمِ ٱلَّذِينَ ظَلَمُواْۚ وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴿٤٥﴾", "w": [["أرأيتكم", "أخبروني."], ["الساعة", "يوم القيامة."], ["يكشف", "يزيل ويُبعد ويُنجي."], ["يتضرّعون", "يتذلّلون في الدعاء خاضعين."], ["بغتة", "فجأة وعلى حين غفلة."], ["مبلسون", "آيسون قانطون متحسّرون."], ["دابر القوم", "آخرهم، أي أُهلكوا من أولهم إلى آخرهم."], ["الحمد لله", "الثناء بالجميل والشكر لله دون سواه."]], "m": "ما زال السياق في هداية المشركين: قل أخبروني إن أتاكم عذاب الله اليوم، أو أتتكم الساعة، أغير الله تدعون ليصرفه عنكم إن كنتم صادقين؟ بل إياه تدعون فيكشف ما تدعون إليه إن شاء، وتنسون ما تشركون، ليأسكم من إجابتها. ثم أخبر رسوله: ولقد أرسلنا إلى أمم من قبلك رسلاً فكذّبوهم، فأخذناهم بالبأساء والضراء من حروب ومجاعات وأمراض لعلهم يتضرّعون فيرجعون، فلولا إذ جاءهم بأسنا تضرّعوا، ولكن قست قلوبهم وزيّن لهم الشيطان ما كانوا يعملون. فلما نسوا ما ذُكّروا به فتحنا عليهم أبواب كل شيء من الخيرات استدراجاً، حتى إذا فرحوا بما أوتوا واطمأنّوا أخذناهم بغتة فإذا هم آيسون متحسّرون، فقُطع دابر القوم الذين ظلموا، والحمد لله رب العالمين، ناصر أوليائه ومهلك أعدائه.", "h": ["من غريب أحوال الإنسان المشرك أنه في حال الشدة الحقيقية يدعو الله وحده، ولا يدعو معه الآلهة الباطلة التي كان يدعوها في حال الرخاء.", "بيان سنة الله تعالى في إهلاك الأمم.", "إذا رأيت الأمة قد فسقت عن أمر ربها فعوقبت فلم تتّعظ، واستمرت على فسقها، وبسط الله لها في الرزق، فاعلم أنها قد استُدرجت للهلاك.", "شؤم الظلم هلاك الظالمين.", "الإرشاد إلى حمد الله تعالى عند نهاية كل عمل."], "k": "«فتحنا عليهم أبواب كل شيء»… هل النعم التي عندي تقرّبني من ربي، أم أنا مُستدرَج بها وأنا لا أشعر؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;